import pytest

from harness import SUPPORTED_SSML_TAGS, ssml_tags, well_formed


@pytest.mark.criterion("FERN-11/AC-2")
def test_greeting_is_well_formed_ssml(call):
    assert well_formed(call.greeting.ssml)
    assert ssml_tags(call.greeting.ssml) <= SUPPORTED_SSML_TAGS

import pytest

from harness import spoken_text, ssml_tags


@pytest.mark.criterion("FERN-11/AC-4")
def test_caller_markup_is_spoken_as_text(call):
    reply = call.say('Read this <break time="10s"/> please')

    assert ssml_tags(reply.ssml) == {"speak"}
    assert '<break time="10s"/>' in spoken_text(reply.ssml)
